// Protocol model follows
// https://sites.google.com/view/astro-gadget/control-of-focusers/focusdreampro
// and https://github.com/sirJolo/ascom-jolo-focuser. Commands carry no
// terminator; the controller parses a request once the bytes stop arriving.

#define _DEFAULT_SOURCE
#define _XOPEN_SOURCE 600

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "../../../indigo_test/simulator_common/serial_simulator_common.h"
#include "../../../indigo_test/simulator_common/serial_motion.h"

#define COMMAND_LENGTH 32

typedef struct {
	bool headless;
	bool trace;
	const char *ready_file;
} simulator_options;

static simulator_options options = {
	.headless = false,
	.trace = true,
	.ready_file = NULL
};

static const char *simulator_name = "focuser_focusdreampro";
// normal            - FocusDreamPro with a temperature probe
// jolo              - Astrojolo controller, otherwise identical
// no-temperature    - controller without a probe, answers T:false
// no-identity       - silent controller, the # transaction times out
// temperature-error - identity works, every T reply is malformed
// move-error        - M: and R: are rejected instead of echoed
// abort-error       - H is rejected instead of echoed
static const char *profile = "normal";
static volatile sig_atomic_t running = 1;
static int serial_fd = -1;
static serial_motion motion;
static int max_position = 1000000;
// The controller's S: value is a per step delay, but one unit of it is about
// 44 us of real delay and not the microsecond the name suggests, and every step
// carries about 0.15 ms of fixed overhead on top. Measured on an AstroGadget
// FocusDreamPro over moves of 500 to 2000 steps: 22.1 ms per step at S:500,
// 11.14 at S:250, 4.96 at S:110, 1.91 at S:40, 0.53 at S:10 and 0.40 at S:5.
#define STEP_OVERHEAD_S 0.000151
#define STEP_DELAY_UNIT_S 0.000044
static int step_delay = 500;
static int duty_cycle = 20;
static double temperature = 21.5;
static bool stalled, split;
// Test hooks, both optional and named by environment variables:
//   INDIGO_FOCUSDREAMPRO_EVENTS  every request as "<time> RX <request>"
//   INDIGO_FOCUSDREAMPRO_FAULT   "<request prefix> <action> [count]"; actions: silent, error (ERR), malformed
//                                (<letter>:x), delay (reply held 400 ms), ignore (H not executed, no reply),
//                                stall (M: reports motion but never moves), false (T:false), implausible
//                                (T:150.0), close; or "external <position>" (motion the driver did not command)
//                                and "split 1" (every reply written in two parts)
static const char *event_path, *fault_path;

static void usage(const char *name) {
	printf("AstroGadget FocusDreamPro serial simulator\n");
	printf("Usage: %s [OPTIONS]\n", name);
	printf("  --headless              Disable terminal-oriented output\n");
	printf("  --ready-file <path>     Write INDIGO_SIMULATOR_PORT after PTY setup\n");
	printf("  --trace                 Log protocol requests and replies\n");
	printf("  --profile <name>        normal, jolo, no-temperature, no-identity,\n");
	printf("                          temperature-error, move-error or abort-error\n");
	printf("  -h, --help              Show this help and exit\n");
}

static void signal_handler(int sig) {
	(void)sig;
	running = 0;
	if (serial_fd >= 0) {
		close(serial_fd);
		serial_fd = -1;
	}
}

static bool parse_args(int argc, char *argv[]) {
	for (int i = 1; i < argc; i++) {
		if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
			usage(argv[0]);
			exit(0);
		} else if (!strcmp(argv[i], "--headless")) {
			options.headless = true;
			options.trace = false;
		} else if (!strcmp(argv[i], "--trace")) {
			options.trace = true;
		} else if (!strcmp(argv[i], "--ready-file")) {
			if (++i == argc) {
				fprintf(stderr, "--ready-file requires a path\n");
				return false;
			}
			options.ready_file = argv[i];
		} else if (!strcmp(argv[i], "--profile")) {
			if (++i == argc) {
				fprintf(stderr, "--profile requires a name\n");
				return false;
			}
			profile = argv[i];
		} else {
			fprintf(stderr, "Unknown option '%s'\n", argv[i]);
			return false;
		}
	}
	return true;
}

static int clamp_position(int value) {
	if (value < 0) {
		return 0;
	}
	if (value > max_position) {
		return max_position;
	}
	return value;
}

static void send_line(const char *line) {
	serial_simulator_trace_line(options.trace, "->", line);
	if (split && strlen(line) > 1) {
		size_t first = strlen(line) / 2;
		serial_simulator_write_all(serial_fd, line, first);
		usleep(30000);
		serial_simulator_write_all(serial_fd, line + first, strlen(line) - first);
	} else {
		serial_simulator_write_all(serial_fd, line, strlen(line));
	}
	serial_simulator_write_all(serial_fd, "\n", 1);
}

static void log_request(const char *command) {
	FILE *file = event_path ? fopen(event_path, "a") : NULL;
	if (file) {
		fprintf(file, "%.6f RX %s\n", serial_motion_time(), command);
		fclose(file);
	}
}

// Returns the action of a fault matching this request, consuming one count of it.
static bool take_fault(const char *command, char *action, size_t size) {
	FILE *file = fault_path ? fopen(fault_path, "r") : NULL;
	if (!file) {
		return false;
	}
	char key[32] = "", found[32] = "";
	int count = 1;
	int fields = fscanf(file, "%31s %31s %d", key, found, &count);
	fclose(file);
	if (fields < 2) {
		return false;
	}
	if (!strcmp(key, "external")) {
		serial_motion_start(&motion, clamp_position(atoi(found)), 1.0 / (STEP_OVERHEAD_S + STEP_DELAY_UNIT_S * step_delay));
		unlink(fault_path);
		return false;
	}
	if (!strcmp(key, "split")) {
		split = atoi(found) != 0;
		unlink(fault_path);
		return false;
	}
	if (strncmp(command, key, strlen(key))) {
		return false;
	}
	if (fields == 3 && count > 1 && (file = fopen(fault_path, "w"))) {
		fprintf(file, "%s %s %d\n", key, found, count - 1);
		fclose(file);
	} else {
		unlink(fault_path);
	}
	snprintf(action, size, "%s", found);
	return true;
}

static void handle_command(const char *command) {
	char response[COMMAND_LENGTH] = { 0 }, action[32] = "";
	serial_simulator_trace_line(options.trace, "<-", command);
	log_request(command);
	if (take_fault(command, action, sizeof(action))) {
		if (!strcmp(action, "silent")) {
			return;
		} else if (!strcmp(action, "error")) {
			send_line("ERR");
			return;
		} else if (!strcmp(action, "malformed")) {
			snprintf(response, sizeof(response), "%c:x", command[0]);
			send_line(response);
			return;
		} else if (!strcmp(action, "ignore")) {
			return;
		} else if (!strcmp(action, "close")) {
			running = 0;
			close(serial_fd);
			serial_fd = -1;
			return;
		} else if (!strcmp(action, "false")) {
			send_line("T:false");
			return;
		} else if (!strcmp(action, "implausible")) {
			send_line("T:150.0");
			return;
		} else if (!strcmp(action, "stall")) {
			stalled = true;
			send_line(command);
			return;
		} else if (!strcmp(action, "delay")) {
			usleep(400000);
		}
	}
	if (!strcmp(command, "#")) {
		if (!strcmp(profile, "no-identity")) {
			return;
		}
		send_line(!strcmp(profile, "jolo") ? "Jolo 1.0" : "FD");
	} else if (!strcmp(command, "T")) {
		if (!strcmp(profile, "no-temperature")) {
			send_line("T:false");
		} else if (!strcmp(profile, "temperature-error")) {
			send_line("ERR");
		} else {
			snprintf(response, sizeof(response), "T:%.1f", temperature);
			send_line(response);
		}
	} else if (!strcmp(command, "I")) {
		serial_motion_update(&motion);
		send_line(stalled || motion.duration > 0 ? "I:true" : "I:false");
	} else if (!strcmp(command, "P")) {
		snprintf(response, sizeof(response), "P:%d", (int)(stalled ? motion.position : serial_motion_update(&motion)));
		send_line(response);
	} else if (!strcmp(command, "X") || !strcmp(command, "S") || !strcmp(command, "D")) {
		// The controller has no readback for these: the bare query is answered
		// with the bare command letter and no value.
		send_line(command);
	} else if (!strncmp(command, "X:", 2)) {
		max_position = atoi(command + 2);
		if (max_position < 0) {
			max_position = 0;
		}
		serial_motion_sync(&motion, clamp_position((int)serial_motion_update(&motion)));
		send_line(command);
	} else if (!strncmp(command, "S:", 2)) {
		step_delay = atoi(command + 2);
		if (step_delay < 1) {
			step_delay = 1;
		}
		send_line(command);
	} else if (!strncmp(command, "D:", 2)) {
		duty_cycle = atoi(command + 2);
		(void)duty_cycle;
		send_line(command);
	} else if (!strncmp(command, "M:", 2)) {
		if (!strcmp(profile, "move-error")) {
			send_line("ERR");
			return;
		}
		serial_motion_start(&motion, clamp_position(atoi(command + 2)), 1.0 / (STEP_OVERHEAD_S + STEP_DELAY_UNIT_S * step_delay));
		send_line(command);
	} else if (!strncmp(command, "R:", 2)) {
		if (!strcmp(profile, "move-error")) {
			send_line("ERR");
			return;
		}
		serial_motion_sync(&motion, clamp_position(atoi(command + 2)));
		send_line(command);
	} else if (!strcmp(command, "H")) {
		stalled = false;
		serial_motion_stop(&motion);
		send_line(!strcmp(profile, "abort-error") ? "ERR" : "H");
	}
}

static void run_protocol_loop(void) {
	char buffer[COMMAND_LENGTH] = { 0 };
	size_t length = 0;
	while (running) {
		char c = '\0';
		ssize_t bytes_read = read(serial_fd, &c, 1);
		if (bytes_read < 0) {
			if (errno == EINTR) {
				continue;
			}
			if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EIO) {
				// A gap in the incoming bytes does NOT end a command. The
				// controller acts on a request only once it has seen the
				// terminating newline, so an unterminated request stays in the
				// buffer and is never answered.
				usleep(1000);
				continue;
			}
			perror("read");
			break;
		}
		if (bytes_read == 0) {
			continue;
		}
		if (c == '\n') {
			buffer[length] = '\0';
			if (length > 0) {
				handle_command(buffer);
			}
			length = 0;
			buffer[0] = '\0';
			continue;
		}
		if (c == '\r') {
			continue;
		}
		if (length < sizeof(buffer) - 1) {
			buffer[length++] = c;
		} else {
			length = 0;
			buffer[0] = '\0';
		}
	}
}

int main(int argc, char *argv[]) {
	char port[256] = { 0 };
	if (!parse_args(argc, argv)) {
		return 1;
	}
	signal(SIGTERM, signal_handler);
	signal(SIGINT, signal_handler);
	serial_motion_sync(&motion, 0);
	event_path = getenv("INDIGO_FOCUSDREAMPRO_EVENTS");
	fault_path = getenv("INDIGO_FOCUSDREAMPRO_FAULT");
	serial_fd = serial_simulator_open_pty(port, sizeof(port));
	if (serial_fd < 0) {
		return 1;
	}
	if (options.ready_file != NULL && !serial_simulator_write_ready_file(options.ready_file, simulator_name, port)) {
		close(serial_fd);
		return 1;
	}
	if (!options.headless) {
		printf("AstroGadget FocusDreamPro simulator ready on %s\n", port);
	}
	run_protocol_loop();
	if (serial_fd >= 0) {
		close(serial_fd);
	}
	return 0;
}
